INSERT IGNORE INTO `teacher_evaluations` (`id`, `title`, `instructions`, `sent_at_utc`, `due_at_utc`, `term_id`, `created_by_user_id`, `created_at_utc`, `updated_at_utc`) VALUES
(1, 'Teacher evaluation - first term', 'Please answer honestly. Your answers are anonymous: your teacher and your classmates do not see who wrote them. Rate from 1 (poor) to 5 (excellent).', (TIMESTAMP(UTC_DATE()) + INTERVAL -514800 SECOND), (TIMESTAMP(UTC_DATE()) + INTERVAL 752400 SECOND), 2, 4, (TIMESTAMP(UTC_DATE()) + INTERVAL -691200 SECOND), (TIMESTAMP(UTC_DATE()) + INTERVAL -514800 SECOND));
INSERT IGNORE INTO `evaluation_questions` (`id`, `evaluation_id`, `position`, `text`, `kind`, `category`, `created_at_utc`, `updated_at_utc`, `options_text`) VALUES
(1, 1, 1, 'The teacher explains the lessons clearly.', 'Likert', 'Teaching', (TIMESTAMP(UTC_DATE()) + INTERVAL -691200 SECOND), (TIMESTAMP(UTC_DATE()) + INTERVAL -691200 SECOND), NULL),
(2, 1, 2, 'The teacher is prepared for every class.', 'Likert', 'Preparation', (TIMESTAMP(UTC_DATE()) + INTERVAL -691200 SECOND), (TIMESTAMP(UTC_DATE()) + INTERVAL -691200 SECOND), NULL),
(3, 1, 3, 'The teacher keeps the class orderly and respectful.', 'Likert', 'Classroom management', (TIMESTAMP(UTC_DATE()) + INTERVAL -691200 SECOND), (TIMESTAMP(UTC_DATE()) + INTERVAL -691200 SECOND), NULL),
(4, 1, 4, 'How often does the teacher answer questions and give feedback on time?', 'Frequency', 'Communication', (TIMESTAMP(UTC_DATE()) + INTERVAL -691200 SECOND), (TIMESTAMP(UTC_DATE()) + INTERVAL -691200 SECOND), NULL),
(5, 1, 5, 'The activities and quizzes match what was taught.', 'Likert', 'Assessment', (TIMESTAMP(UTC_DATE()) + INTERVAL -691200 SECOND), (TIMESTAMP(UTC_DATE()) + INTERVAL -691200 SECOND), NULL),
(6, 1, 6, 'Overall, how would you rate this teacher?', 'Performance', 'Overall', (TIMESTAMP(UTC_DATE()) + INTERVAL -691200 SECOND), (TIMESTAMP(UTC_DATE()) + INTERVAL -691200 SECOND), NULL),
(7, 1, 7, 'Would you recommend this teacher to other students?', 'Binary', 'Overall', (TIMESTAMP(UTC_DATE()) + INTERVAL -691200 SECOND), (TIMESTAMP(UTC_DATE()) + INTERVAL -691200 SECOND), NULL),
(8, 1, 8, 'Rank what helps you learn the most, from the first (best) to the last.', 'Ranking', 'Overall', (TIMESTAMP(UTC_DATE()) + INTERVAL -691200 SECOND), (TIMESTAMP(UTC_DATE()) + INTERVAL -691200 SECOND), 'Explanations in class\nActivities and worksheets\nQuizzes\nTask performances (projects)'),
(9, 1, 9, 'What does your teacher do well? Select all that apply.', 'SelectAll', 'Comments', (TIMESTAMP(UTC_DATE()) + INTERVAL -691200 SECOND), (TIMESTAMP(UTC_DATE()) + INTERVAL -691200 SECOND), 'Explains clearly\nGives helpful feedback\nMakes the lessons interesting\nIs fair to everybody\nIs patient\nIs always prepared'),
(10, 1, 10, 'What does your teacher do well?', 'Comment', 'Comments', (TIMESTAMP(UTC_DATE()) + INTERVAL -691200 SECOND), (TIMESTAMP(UTC_DATE()) + INTERVAL -691200 SECOND), NULL),
(11, 1, 11, 'What can your teacher do better?', 'Comment', 'Comments', (TIMESTAMP(UTC_DATE()) + INTERVAL -691200 SECOND), (TIMESTAMP(UTC_DATE()) + INTERVAL -691200 SECOND), NULL);
