(3, 1, 21, 'I can come too. Can someone explain the trial balance?', NULL, (TIMESTAMP(UTC_DATE()) + INTERVAL -252000 SECOND), (TIMESTAMP(UTC_DATE()) + INTERVAL -252000 SECOND)),
(4, 1, 7, 'Read Handout 3 first, then try the task performance. I will answer questions in class.', 3, (TIMESTAMP(UTC_DATE()) + INTERVAL -241200 SECOND), (TIMESTAMP(UTC_DATE()) + INTERVAL -241200 SECOND)),
(5, 2, 22, 'Here are 5 practice problems for the quiz. Try them before Friday.', NULL, (TIMESTAMP(UTC_DATE()) + INTERVAL -165600 SECOND), (TIMESTAMP(UTC_DATE()) + INTERVAL -165600 SECOND)),
(6, 3, 7, 'Reminder: the grades of the first term are due next week.', NULL, (TIMESTAMP(UTC_DATE()) + INTERVAL -75600 SECOND), (TIMESTAMP(UTC_DATE()) + INTERVAL -75600 SECOND)),
(7, 3, 8, 'Thanks. I will send the review materials here.', 6, (TIMESTAMP(UTC_DATE()) + INTERVAL -72000 SECOND), (TIMESTAMP(UTC_DATE()) + INTERVAL -72000 SECOND));
